-- IPDAMS 0.1.0. MySQL 8 / MariaDB 10.6+, utf8mb4, InnoDB.
-- All monetary amounts are DECIMAL; avoid FLOAT for financial postings.
CREATE TABLE organizations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(24) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, kind ENUM('DIVISION','SCHOOL') NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(150) NOT NULL, role ENUM('SUPER_ADMIN','DIVISION','SCHOOL','VIEWER') NOT NULL DEFAULT 'SCHOOL', active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE user_organization_scopes (user_id BIGINT UNSIGNED NOT NULL, organization_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,organization_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(organization_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE departments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE employees (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(160) NOT NULL, position_title VARCHAR(160) NULL) ENGINE=InnoDB;
CREATE TABLE employee_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id BIGINT UNSIGNED NOT NULL, organization_id BIGINT UNSIGNED NOT NULL, designation VARCHAR(160) NOT NULL, effective_from DATE NOT NULL, effective_to DATE NULL, FOREIGN KEY(employee_id) REFERENCES employees(id), FOREIGN KEY(organization_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE bac_terms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, starts DATE NOT NULL, ends DATE NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE bac_members (term_id BIGINT UNSIGNED NOT NULL, employee_id BIGINT UNSIGNED NOT NULL, role_title VARCHAR(100) NOT NULL, PRIMARY KEY(term_id,employee_id), FOREIGN KEY(term_id) REFERENCES bac_terms(id), FOREIGN KEY(employee_id) REFERENCES employees(id)) ENGINE=InnoDB;
CREATE TABLE suppliers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(200) NOT NULL, tax_id VARCHAR(40) NULL, address TEXT NULL, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE funds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, fiscal_year SMALLINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, source_code VARCHAR(60) NOT NULL, UNIQUE KEY uq_fund(organization_id,fiscal_year,source_code), FOREIGN KEY(organization_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE fund_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, fund_id BIGINT UNSIGNED NOT NULL, event_type ENUM('ALLOTMENT','RELEASE','OBLIGATION','OBLIGATION_REVERSAL','DISBURSEMENT','DISBURSEMENT_REVERSAL','PENDING_TAX','PENDING_TAX_REVERSAL','CONFIRMED_CREDIT','ADJUSTMENT') NOT NULL, amount DECIMAL(18,2) NOT NULL, reference_type VARCHAR(40) NOT NULL, reference_id BIGINT UNSIGNED NOT NULL, reason VARCHAR(500) NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(fund_id) REFERENCES funds(id), FOREIGN KEY(organization_id) REFERENCES organizations(id), INDEX ix_fund(fund_id,event_type)) ENGINE=InnoDB;
CREATE TABLE units (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL) ENGINE=InnoDB;
CREATE TABLE item_catalog (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, unit_id BIGINT UNSIGNED NOT NULL, category ENUM('SUPPLY','SEMI_EXPENDABLE','PPE','TEXTBOOK','SERVICE') NOT NULL DEFAULT 'SUPPLY', active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(unit_id) REFERENCES units(id)) ENGINE=InnoDB;
CREATE TABLE uacs_accounts (code VARCHAR(32) PRIMARY KEY, account_name VARCHAR(180) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE item_account_mappings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, item_id BIGINT UNSIGNED NOT NULL, uacs_code VARCHAR(32) NOT NULL, effective_from DATE NOT NULL, effective_to DATE NULL, FOREIGN KEY(item_id) REFERENCES item_catalog(id), FOREIGN KEY(uacs_code) REFERENCES uacs_accounts(code)) ENGINE=InnoDB;
CREATE TABLE tax_atcs (code VARCHAR(24) PRIMARY KEY, description VARCHAR(180) NOT NULL) ENGINE=InnoDB;
CREATE TABLE tax_rate_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, atc_code VARCHAR(24) NOT NULL, rate DECIMAL(10,6) NOT NULL, starts DATE NOT NULL, ends DATE NULL, authority_reference VARCHAR(255) NULL, FOREIGN KEY(atc_code) REFERENCES tax_atcs(code)) ENGINE=InnoDB;
CREATE TABLE configuration_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NULL, config_key VARCHAR(80) NOT NULL, config_json JSON NOT NULL, effective_from DATE NOT NULL, review_note VARCHAR(500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE document_counters (organization_id BIGINT UNSIGNED NOT NULL, doc_type VARCHAR(16) NOT NULL, period CHAR(7) NOT NULL, next_sequence INT UNSIGNED NOT NULL, PRIMARY KEY(organization_id,doc_type,period), FOREIGN KEY(organization_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE document_registry (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, doc_type VARCHAR(16) NOT NULL, period CHAR(7) NOT NULL, display_number CHAR(12) NOT NULL, entity_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_number(organization_id,doc_type,display_number), UNIQUE KEY uq_doc_entity(doc_type,entity_id), FOREIGN KEY(organization_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE document_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, doc_type VARCHAR(16) NOT NULL, entity_id BIGINT UNSIGNED NOT NULL, version_no INT UNSIGNED NOT NULL, snapshot_json JSON NOT NULL, reason VARCHAR(500) NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_version(doc_type,entity_id,version_no), INDEX ix_document(organization_id,doc_type,entity_id)) ENGINE=InnoDB;
CREATE TABLE document_links (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, source_type VARCHAR(16) NOT NULL, source_id BIGINT UNSIGNED NOT NULL, target_type VARCHAR(16) NOT NULL, target_id BIGINT UNSIGNED NOT NULL, UNIQUE KEY uq_doc_link(source_type,source_id,target_type,target_id)) ENGINE=InnoDB;
CREATE TABLE attachments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, doc_type VARCHAR(16) NOT NULL, entity_id BIGINT UNSIGNED NOT NULL, stored_filename VARCHAR(200) NOT NULL, original_name VARCHAR(200) NOT NULL, mime VARCHAR(80) NOT NULL, sha256 CHAR(64) NOT NULL, uploaded_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX ix_attachment(organization_id,doc_type,entity_id)) ENGINE=InnoDB;
CREATE TABLE audit_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NULL, actor_id BIGINT UNSIGNED NOT NULL, event_type VARCHAR(80) NOT NULL, entity_type VARCHAR(24) NOT NULL, entity_id BIGINT UNSIGNED NOT NULL, details JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX ix_audit(organization_id,created_at)) ENGINE=InnoDB;
CREATE TABLE idempotency_keys (user_id BIGINT UNSIGNED NOT NULL, request_key VARCHAR(100) NOT NULL, response_json JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,request_key)) ENGINE=InnoDB;
CREATE TABLE procurement_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, title VARCHAR(240) NOT NULL, method VARCHAR(80) NOT NULL DEFAULT 'REVIEW_REQUIRED', created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(organization_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE purchase_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, transaction_id BIGINT UNSIGNED NOT NULL, fund_id BIGINT UNSIGNED NOT NULL, purpose TEXT NOT NULL, requesting_unit VARCHAR(160) NOT NULL, status ENUM('DRAFT','FINALIZED','CANCELLED') NOT NULL DEFAULT 'DRAFT', display_number CHAR(12) NULL, total DECIMAL(18,2) NOT NULL DEFAULT 0, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(transaction_id) REFERENCES procurement_transactions(id), FOREIGN KEY(fund_id) REFERENCES funds(id), INDEX ix_pr_org(organization_id,status)) ENGINE=InnoDB;
CREATE TABLE pr_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, pr_id BIGINT UNSIGNED NOT NULL, item_id BIGINT UNSIGNED NOT NULL, description_snapshot VARCHAR(255) NOT NULL, unit_snapshot VARCHAR(80) NOT NULL, quantity DECIMAL(14,3) NOT NULL, estimated_unit_price DECIMAL(18,2) NOT NULL, FOREIGN KEY(pr_id) REFERENCES purchase_requests(id), FOREIGN KEY(item_id) REFERENCES item_catalog(id)) ENGINE=InnoDB;
CREATE TABLE rfqs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, pr_id BIGINT UNSIGNED NOT NULL, status ENUM('DRAFT','FINALIZED','CANCELLED') NOT NULL DEFAULT 'FINALIZED', display_number CHAR(12) NULL, issued_at DATE NOT NULL, created_by BIGINT UNSIGNED NOT NULL, FOREIGN KEY(pr_id) REFERENCES purchase_requests(id)) ENGINE=InnoDB;
CREATE TABLE supplier_quotes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, rfq_id BIGINT UNSIGNED NOT NULL, supplier_id BIGINT UNSIGNED NOT NULL, offered_at DATE NULL, evidence_note VARCHAR(500) NULL, FOREIGN KEY(rfq_id) REFERENCES rfqs(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id)) ENGINE=InnoDB;
CREATE TABLE quote_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, supplier_quote_id BIGINT UNSIGNED NOT NULL, pr_line_id BIGINT UNSIGNED NOT NULL, offered_price DECIMAL(18,2) NOT NULL, compliant TINYINT(1) NOT NULL DEFAULT 0, FOREIGN KEY(supplier_quote_id) REFERENCES supplier_quotes(id), FOREIGN KEY(pr_line_id) REFERENCES pr_lines(id)) ENGINE=InnoDB;
CREATE TABLE awards (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, pr_id BIGINT UNSIGNED NOT NULL, rfq_id BIGINT UNSIGNED NULL, supplier_id BIGINT UNSIGNED NOT NULL, determination_note TEXT NOT NULL, status ENUM('FINALIZED','CANCELLED') NOT NULL DEFAULT 'FINALIZED', display_number CHAR(12) NULL, created_by BIGINT UNSIGNED NOT NULL, FOREIGN KEY(pr_id) REFERENCES purchase_requests(id), FOREIGN KEY(rfq_id) REFERENCES rfqs(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id)) ENGINE=InnoDB;
CREATE TABLE purchase_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, pr_id BIGINT UNSIGNED NOT NULL, award_id BIGINT UNSIGNED NOT NULL, supplier_id BIGINT UNSIGNED NOT NULL, status ENUM('FINALIZED','CANCELLED') NOT NULL DEFAULT 'FINALIZED', display_number CHAR(12) NULL, created_by BIGINT UNSIGNED NOT NULL, FOREIGN KEY(pr_id) REFERENCES purchase_requests(id), FOREIGN KEY(award_id) REFERENCES awards(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id)) ENGINE=InnoDB;
CREATE TABLE po_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, po_id BIGINT UNSIGNED NOT NULL, pr_line_id BIGINT UNSIGNED NOT NULL, item_id BIGINT UNSIGNED NOT NULL, quantity DECIMAL(14,3) NOT NULL, unit_price DECIMAL(18,2) NOT NULL, FOREIGN KEY(po_id) REFERENCES purchase_orders(id), FOREIGN KEY(pr_line_id) REFERENCES pr_lines(id)) ENGINE=InnoDB;
CREATE TABLE po_amendments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, po_id BIGINT UNSIGNED NOT NULL, version_no INT NOT NULL, old_json JSON NOT NULL, new_json JSON NOT NULL, reason TEXT NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_amend(po_id,version_no)) ENGINE=InnoDB;
CREATE TABLE iars (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, po_id BIGINT UNSIGNED NOT NULL, status ENUM('FINALIZED','CANCELLED') NOT NULL DEFAULT 'FINALIZED', display_number CHAR(12) NULL, delivered_at DATE NOT NULL, accepted_at DATE NOT NULL, created_by BIGINT UNSIGNED NOT NULL, FOREIGN KEY(po_id) REFERENCES purchase_orders(id)) ENGINE=InnoDB;
CREATE TABLE iar_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, iar_id BIGINT UNSIGNED NOT NULL, po_line_id BIGINT UNSIGNED NOT NULL, delivered_qty DECIMAL(14,3) NOT NULL, accepted_qty DECIMAL(14,3) NOT NULL, rejected_qty DECIMAL(14,3) NOT NULL DEFAULT 0, accepted_amount DECIMAL(18,2) NOT NULL, FOREIGN KEY(iar_id) REFERENCES iars(id), FOREIGN KEY(po_line_id) REFERENCES po_lines(id), INDEX ix_accept(po_line_id)) ENGINE=InnoDB;
CREATE TABLE advances (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, iar_line_id BIGINT UNSIGNED NOT NULL, original_payer VARCHAR(180) NOT NULL, source ENUM('PERSONAL','OTHER_SCHOOL_FUND') NOT NULL, amount DECIMAL(18,2) NOT NULL, paid_at DATE NOT NULL, evidence_reference VARCHAR(255) NOT NULL, created_by BIGINT UNSIGNED NOT NULL, UNIQUE KEY uq_advance(iar_line_id,original_payer,evidence_reference), FOREIGN KEY(iar_line_id) REFERENCES iar_lines(id)) ENGINE=InnoDB;
CREATE TABLE disbursement_vouchers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, fund_id BIGINT UNSIGNED NOT NULL, dv_type ENUM('REGULAR','DIRECT','REIMBURSEMENT') NOT NULL, status ENUM('DRAFT','FINALIZED','CANCELLED') NOT NULL DEFAULT 'DRAFT', display_number CHAR(12) NULL, payee VARCHAR(180) NOT NULL, gross DECIMAL(18,2) NOT NULL, deductions DECIMAL(18,2) NOT NULL DEFAULT 0, net DECIMAL(18,2) NOT NULL, bill_reference VARCHAR(255) NULL, reason VARCHAR(500) NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(fund_id) REFERENCES funds(id), INDEX ix_dv_org(organization_id,dv_type,status)) ENGINE=InnoDB;
CREATE TABLE dv_allocation_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, dv_id BIGINT UNSIGNED NOT NULL, pr_id BIGINT UNSIGNED NULL, iar_line_id BIGINT UNSIGNED NULL, advance_id BIGINT UNSIGNED NULL, original_supplier_id BIGINT UNSIGNED NULL, amount DECIMAL(18,2) NOT NULL, FOREIGN KEY(dv_id) REFERENCES disbursement_vouchers(id), FOREIGN KEY(pr_id) REFERENCES purchase_requests(id), FOREIGN KEY(iar_line_id) REFERENCES iar_lines(id), FOREIGN KEY(advance_id) REFERENCES advances(id), FOREIGN KEY(original_supplier_id) REFERENCES suppliers(id)) ENGINE=InnoDB;
CREATE TABLE dv_accounting_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, dv_id BIGINT UNSIGNED NOT NULL, version_no INT UNSIGNED NOT NULL, reason VARCHAR(500) NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_dv_accounting(dv_id,version_no), FOREIGN KEY(dv_id) REFERENCES disbursement_vouchers(id)) ENGINE=InnoDB;
CREATE TABLE voucher_accounting_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, accounting_version_id BIGINT UNSIGNED NOT NULL, uacs_code VARCHAR(32) NOT NULL, debit DECIMAL(18,2) NOT NULL DEFAULT 0, credit DECIMAL(18,2) NOT NULL DEFAULT 0, explanation VARCHAR(255) NULL, FOREIGN KEY(accounting_version_id) REFERENCES dv_accounting_versions(id), FOREIGN KEY(uacs_code) REFERENCES uacs_accounts(code)) ENGINE=InnoDB;
CREATE TABLE withholding_components (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, dv_id BIGINT UNSIGNED NOT NULL, dv_allocation_line_id BIGINT UNSIGNED NULL, atc_code VARCHAR(24) NOT NULL, rate_version_id BIGINT UNSIGNED NOT NULL, tax_base DECIMAL(18,2) NOT NULL, amount DECIMAL(18,2) NOT NULL, disposition ENUM('REMIT','SCHOOL_UTILIZATION') NOT NULL, fund_id BIGINT UNSIGNED NULL, FOREIGN KEY(dv_id) REFERENCES disbursement_vouchers(id), FOREIGN KEY(rate_version_id) REFERENCES tax_rate_versions(id)) ENGINE=InnoDB;
CREATE TABLE tax_disposition_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, component_id BIGINT UNSIGNED NOT NULL, state ENUM('ASSESSED','PENDING','CONFIRMED_CREDIT','REMITTED','REVERSED') NOT NULL, amount DECIMAL(18,2) NOT NULL, evidence_reference VARCHAR(255) NOT NULL, authority_reference VARCHAR(255) NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(component_id) REFERENCES withholding_components(id)) ENGINE=InnoDB;
CREATE TABLE bank_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, bank_name VARCHAR(120) NOT NULL, account_label VARCHAR(120) NOT NULL, masked_account VARCHAR(20) NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE checks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, bank_account_id BIGINT UNSIGNED NOT NULL, dv_id BIGINT UNSIGNED NOT NULL, check_number VARCHAR(40) NOT NULL, status ENUM('ISSUED','SIGNED','RELEASED','CLEARED','CANCELLED','STOPPED','STALE','REPLACED') NOT NULL DEFAULT 'ISSUED', amount DECIMAL(18,2) NOT NULL, replaces_check_id BIGINT UNSIGNED NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_check(bank_account_id,check_number), FOREIGN KEY(bank_account_id) REFERENCES bank_accounts(id), FOREIGN KEY(dv_id) REFERENCES disbursement_vouchers(id)) ENGINE=InnoDB;
CREATE TABLE payment_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, check_id BIGINT UNSIGNED NOT NULL, event_type VARCHAR(40) NOT NULL, evidence_reference VARCHAR(255) NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(check_id) REFERENCES checks(id)) ENGINE=InnoDB;
CREATE TABLE bank_reconciliations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, bank_account_id BIGINT UNSIGNED NOT NULL, period CHAR(7) NOT NULL, statement_balance DECIMAL(18,2) NOT NULL, book_balance DECIMAL(18,2) NOT NULL, notes TEXT NULL, status ENUM('DRAFT','CLOSED') NOT NULL DEFAULT 'DRAFT', UNIQUE KEY uq_recon(bank_account_id,period), FOREIGN KEY(bank_account_id) REFERENCES bank_accounts(id)) ENGINE=InnoDB;
CREATE TABLE reconciliation_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reconciliation_id BIGINT UNSIGNED NOT NULL, kind VARCHAR(50) NOT NULL, amount DECIMAL(18,2) NOT NULL, reference VARCHAR(255) NOT NULL, FOREIGN KEY(reconciliation_id) REFERENCES bank_reconciliations(id)) ENGINE=InnoDB;
CREATE TABLE inventory_lots (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, item_id BIGINT UNSIGNED NOT NULL, iar_line_id BIGINT UNSIGNED NULL, opening_record TINYINT(1) NOT NULL DEFAULT 0, acquisition_cost DECIMAL(18,2) NULL, acquired_on DATE NULL, batch VARCHAR(120) NULL, created_by BIGINT UNSIGNED NOT NULL, FOREIGN KEY(item_id) REFERENCES item_catalog(id), UNIQUE KEY uq_iar_lot(iar_line_id)) ENGINE=InnoDB;
CREATE TABLE stock_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, lot_id BIGINT UNSIGNED NOT NULL, event_type ENUM('RECEIPT','OPENING','RIS_ISSUE','RIS_RETURN','TRANSFER_IN','TRANSFER_OUT','COUNT_ADJUSTMENT','DISPOSAL') NOT NULL, quantity_delta DECIMAL(14,3) NOT NULL, source_type VARCHAR(24) NOT NULL, source_id BIGINT UNSIGNED NOT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_stock_event(lot_id,event_type,source_type,source_id), FOREIGN KEY(lot_id) REFERENCES inventory_lots(id), INDEX ix_lot(lot_id)) ENGINE=InnoDB;
CREATE TABLE requisition_issue_slips (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, source_mode ENUM('PR','DIRECT') NOT NULL, pr_id BIGINT UNSIGNED NULL, requestor VARCHAR(160) NOT NULL, status ENUM('DRAFT','ISSUED','REVERSED') NOT NULL DEFAULT 'DRAFT', display_number CHAR(12) NULL, created_by BIGINT UNSIGNED NOT NULL, FOREIGN KEY(pr_id) REFERENCES purchase_requests(id)) ENGINE=InnoDB;
CREATE TABLE ris_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ris_id BIGINT UNSIGNED NOT NULL, item_id BIGINT UNSIGNED NOT NULL, lot_id BIGINT UNSIGNED NULL, requested_qty DECIMAL(14,3) NOT NULL, issued_qty DECIMAL(14,3) NOT NULL DEFAULT 0, FOREIGN KEY(ris_id) REFERENCES requisition_issue_slips(id), FOREIGN KEY(item_id) REFERENCES item_catalog(id)) ENGINE=InnoDB;
CREATE TABLE assets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, item_id BIGINT UNSIGNED NOT NULL, iar_line_id BIGINT UNSIGNED NULL, property_tag VARCHAR(80) NOT NULL, serial_number VARCHAR(120) NULL, acquisition_cost DECIMAL(18,2) NULL, acquired_on DATE NULL, opening_record TINYINT(1) NOT NULL DEFAULT 0, custodian VARCHAR(180) NULL, location VARCHAR(180) NULL, condition_note VARCHAR(255) NULL, status ENUM('ACTIVE','TRANSFERRED','DISPOSED') NOT NULL DEFAULT 'ACTIVE', UNIQUE KEY uq_tag(organization_id,property_tag), FOREIGN KEY(item_id) REFERENCES item_catalog(id)) ENGINE=InnoDB;
CREATE TABLE accountability_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, asset_id BIGINT UNSIGNED NOT NULL, doc_type ENUM('ICS','PAR') NOT NULL, custodian VARCHAR(160) NOT NULL, status ENUM('FINALIZED','CANCELLED') NOT NULL DEFAULT 'FINALIZED', display_number CHAR(12) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(asset_id) REFERENCES assets(id)) ENGINE=InnoDB;
CREATE TABLE asset_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, asset_id BIGINT UNSIGNED NOT NULL, event_type ENUM('ISSUE','TRANSFER','RETURN','REPAIR','COUNT','DISPOSAL') NOT NULL, from_custodian VARCHAR(160) NULL, to_custodian VARCHAR(160) NULL, reason VARCHAR(500) NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(asset_id) REFERENCES assets(id)) ENGINE=InnoDB;
CREATE TABLE textbook_titles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, isbn VARCHAR(40) NULL, grade VARCHAR(30) NULL, subject VARCHAR(100) NULL, edition VARCHAR(80) NULL, publisher VARCHAR(180) NULL) ENGINE=InnoDB;
CREATE TABLE textbook_batches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, title_id BIGINT UNSIGNED NOT NULL, batch VARCHAR(120) NOT NULL, condition_note VARCHAR(120) NULL, storage VARCHAR(180) NULL, opening_record TINYINT(1) NOT NULL DEFAULT 0, FOREIGN KEY(title_id) REFERENCES textbook_titles(id)) ENGINE=InnoDB;
CREATE TABLE textbook_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, batch_id BIGINT UNSIGNED NOT NULL, quantity_delta INT NOT NULL, event_type ENUM('OPENING','RECEIPT','DISTRIBUTION','RETURN','TRANSFER','LOST','DISPOSAL','COUNT_ADJUSTMENT') NOT NULL, reference VARCHAR(200) NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(batch_id) REFERENCES textbook_batches(id)) ENGINE=InnoDB;
